export class SpeechSynthesisEngine {
  constructor() {
    this.synthesis = window.speechSynthesis;
    this.voice = null;
    this.isSpeaking = false;
  }

  initialize() {
    if (!this.synthesis) return false;

    return new Promise((resolve) => {
      const loadVoices = () => {
        const voices = this.synthesis.getVoices();
        this.voice = voices.find(v => v.lang.startsWith('en-') && v.name.includes('Google')) ||
                     voices.find(v => v.lang.startsWith('en-US')) ||
                     voices.find(v => v.lang.startsWith('en')) ||
                     voices[0] || null;
        resolve(true);
      };

      if (this.synthesis.getVoices().length > 0) loadVoices();
      else this.synthesis.onvoiceschanged = loadVoices;
    });
  }

  speak(text, options = {}) {
    return new Promise((resolve, reject) => {
      if (!this.synthesis) return reject(new Error('Speech Synthesis not supported'));

      this.synthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.voice = this.voice || null;
      utterance.rate = options.rate || 0.9;
      utterance.pitch = options.pitch || 1.0;
      utterance.volume = options.volume || 1.0;

      utterance.onstart = () => { this.isSpeaking = true; if (options.onStart) options.onStart(); };
      utterance.onend = () => { this.isSpeaking = false; if (options.onEnd) options.onEnd(); resolve(); };
      utterance.onerror = (error) => { this.isSpeaking = false; if (options.onError) options.onError(error); reject(error); };

      this.synthesis.speak(utterance);
    });
  }

  stop() { if (this.synthesis) { this.synthesis.cancel(); this.isSpeaking = false; } }
  pause() { if (this.synthesis) this.synthesis.pause(); }
  resume() { if (this.synthesis) this.synthesis.resume(); }
  isSupported() { return !!window.speechSynthesis; }
  getSpeaking() { return this.isSpeaking; }
}
